```javascript
import { mix, sin, time, uniform, uv } from 'three/tsl';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // --- BACKDROP PLANE (gradient #0b0b10 to #16161d) ---
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  const gradColor = mix(
    uniform(new THREE.Color(0x0b0b10)),
    uniform(new THREE.Color(0x16161d)),
    uv().y
  );
  backdropMat.color = gradColor;

  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- CORE PARTICLES (90 instances, red accent, additive) ---
  const coreCount = 90;
  const coreMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(0xff2a38),
    emissive: new THREE.Color(0xff2a38),
    metalness: 0,
    roughness: 1,
    transparent: true,
    blending: THREE.AdditiveBlending,
  });

  // Pulsing emissive intensity: 1.5 to 1.8 at 0.1 Hz
  const pulsedIntensity = mix(
    uniform(1.5),
    uniform(1.8),
    sin(time.mul(0.1 * Math.PI * 2)).mul(0.5).add(0.5)
  );
  coreMat.emissiveIntensity = pulsedIntensity;

  const coreGeom = new THREE.IcosahedronGeometry(0.012, 2);
  const coreMesh = new THREE.InstancedMesh(coreGeom, coreMat, coreCount);

  // Distribute core particles in 0.5-unit sphere at [0, 0, -1.5]
  for (let i = 0; i < coreCount; i++) {
    const phi = Math.random() * Math.PI * 2;
    const theta = Math.acos(Math.random() * 2 - 1);
    const r = Math.random() * 0.5;
    const x = r * Math.sin(theta) * Math.cos(phi);
    const y = r * Math.sin(theta) * Math.sin(phi);
    const z = r * Math.cos(theta) - 1.5;

    const m = new THREE.Matrix4();
    m.setPosition(x, y, z);
    coreMesh.setMatrixAt(i, m);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  group.add(coreMesh);

  // --- FIELD PARTICLES (1110 instances, paper white, self-lit) ---
  const fieldCount = 1200 - coreCount;
  const fieldMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(0xe8ecf2),
    emissive: new THREE.Color(0xe8ecf2),
    emissiveIntensity: 0.9,
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 0.9,
  });

  const fieldGeom = new THREE.IcosahedronGeometry(0.012, 2);
  const fieldMesh = new THREE.InstancedMesh(fieldGeom, fieldMat, fieldCount);

  // Distribute field particles in ellipsoidal shell 6×4×5 centered at [0, 0, -1.5]
  for (let i = 0; i < fieldCount; i++) {
    const u = Math.random();
    const v = Math.random();
    const w = Math.random();

    const theta = Math.acos(2 * u - 1);
    const phi = 2 * Math.PI * v;
    const r = Math.cbrt(w);

    const x = r * 3 * Math.sin(theta) * Math.cos(phi);
    const y = r * 2 * Math.sin(theta) * Math.sin(phi);
    const z = r * 2.5 * Math.cos(theta) - 1.5;

    const m = new THREE.Matrix4();
    m.setPosition(x, y, z);
    fieldMesh.setMatrixAt(i, m);
  }
  fieldMesh.instanceMatrix.needsUpdate = true;
  group.add(fieldMesh);

  // --- TEXT (MSDF-rendered) ---
  // Hero: "NOVA ATELIER" at baseline y=0.5
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 0.62,
    color: '#e8ecf2',
    align: 'center',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  // Subhead: "Precision instruments for the dark hours." at y=-0.25 (0.75 below hero baseline)
  const subheadText = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 0.2,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 500,
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  // Caption: "EST. 2019 / GENEVA AND KYOTO" at y=-2.25
  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 0.09,
    color: '#e8ecf2',
    align: 'center',
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // --- APPLY CINEMATIC PRIMITIVE: particle-emerge ---
  const primitiveResult = ctx.primitives['particle-emerge'](group, {
    count: 1200,
    durationMs: 1400,
  });

  // --- AMBIENT DRIFT: slow group rotation ---
  const driftTimeline = gsap.timeline({ repeat: -1 });
  driftTimeline.to(group.rotation, {
    y: Math.PI * 2,
    duration: 20,
    ease: 'none',
  }, 0);

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    backdropGeom.dispose();
    backdropMat.dispose();
    coreGeom.dispose();
    coreMat.dispose();
    fieldGeom.dispose();
    fieldMat.dispose();

    driftTimeline.kill();
    if (primitiveResult && primitiveResult.cleanup) {
      primitiveResult.cleanup();
    }
  };

  return group;
}
